        ],
        spacing: { before: 240, after: 120 }
      })
    );

    block.tasks.forEach(task => {
      elements.push(
        new Paragraph({
          numbering: { reference: "checkbox", level: 0 },
          children: [new TextRun(task)]
        })
      );
    });
  });

  // Add success metrics section
  elements.push(
