// Helper Functions

function createPhaseOverview(title, bullets) {
  const elements = [
    new Paragraph({
      heading: HeadingLevel.HEADING_2,
      children: [new TextRun(title)]
    })
  ];

  bullets.forEach(bullet => {
    elements.push(
      new Paragraph({
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun(bullet)]
      })
    );
  });

  elements.push(
    new Paragraph({
      children: [new TextRun("")],
      spacing: { after: 240 }
    })
  );

  return elements;
}

