function createTrackingTable() {
  const border = { style: BorderStyle.SINGLE, size: 1, color: "999999" };
  const borders = { top: border, bottom: border, left: border, right: border };

  return new Table({
    width: { size: 100, type: WidthType.PERCENTAGE },
    columnWidths: [3120, 3120, 3120],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders,
            width: { size: 3120, type: WidthType.DXA },
            shading: { fill: "333333", type: ShadingType.CLEAR },
            margins: { top: 120, bottom: 120, left: 120, right: 120 },
            children: [new Paragraph({
              children: [new TextRun({ text: "Metric", bold: true, color: "FFFFFF" })],
              alignment: AlignmentType.CENTER
            })]
          }),
          new TableCell({
            borders,
            width: { size: 3120, type: WidthType.DXA },
            shading: { fill: "333333", type: ShadingType.CLEAR },
            margins: { top: 120, bottom: 120, left: 120, right: 120 },
            children: [new Paragraph({
              children: [new TextRun({ text: "This Week", bold: true, color: "FFFFFF" })],
              alignment: AlignmentType.CENTER
            })]
          }),
          new TableCell({
            borders,
            width: { size: 3120, type: WidthType.DXA },
            shading: { fill: "333333", type: ShadingType.CLEAR },
            margins: { top: 120, bottom: 120, left: 120, right: 120 },
            children: [new Paragraph({
              children: [new TextRun({ text: "Goal", bold: true, color: "FFFFFF" })],
              alignment: AlignmentType.CENTER
            })]
          })
        ]
      }),
      createTrackingRow("New Reviews", "____", "10+"),
      createTrackingRow("Package Sales", "____", "5-8"),
      createTrackingRow("New Memberships", "____", "5-10"),
      createTrackingRow("Laser Utilization %", "____%", "70%"),
      createTrackingRow("Weekly Revenue", "$____", "$15K+"),
      createTrackingRow("Response Time (min)", "____", "< 5")
    ]
  });
}

function createTrackingRow(metric, actual, goal) {
  const border = { style: BorderStyle.SINGLE, size: 1, color: "999999" };
  const borders = { top: border, bottom: border, left: border, right: border };

  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 3120, type: WidthType.DXA },
        shading: { fill: "F5F5F5", type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 120, right: 120 },
        children: [new Paragraph({
          children: [new TextRun({ text: metric, bold: true })]
        })]
      }),
      new TableCell({
        borders,
        width: { size: 3120, type: WidthType.DXA },
        margins: { top: 120, bottom: 120, left: 120, right: 120 },
        children: [new Paragraph({
          children: [new TextRun(actual)],
          alignment: AlignmentType.CENTER
        })]
      }),
      new TableCell({
        borders,
        width: { size: 3120, type: WidthType.DXA },
        margins: { top: 120, bottom: 120, left: 120, right: 120 },
        children: [new Paragraph({
          children: [new TextRun(goal)],
          alignment: AlignmentType.CENTER
        })]
      })
